/* ===================================================================
   MARTSEG - CREDITO DE DESENVOLVIMENTO
   ===================================================================
   Sistema desenvolvido pela Martseg especialmente para a Clarity Glass.
   Este script injeta o rodapé de crédito (logo + texto) em todas as
   páginas do sistema. Para atualizar a logo, substitua o arquivo
   assets/martseg-logo.jpeg e regenere o bloco abaixo.
   =================================================================== */

window.MARTSEG_LOGO = 'data:image/jpeg;base64,';

document.addEventListener('DOMContentLoaded', function () {
  var footer = document.querySelector('.footer');
  if (!footer) return;
  if (footer.querySelector('.footer-brand')) return;

  var brand = document.createElement('div');
  brand.className = 'footer-brand';

  var img = document.createElement('img');
  img.className = 'martseg-logo';
  img.style.height = '28px';
  img.style.width = 'auto';
  img.style.maxHeight = '28px';
  img.style.maxWidth = '28px';
  img.src = window.MARTSEG_LOGO;
  img.alt = 'Martseg';
  img.title = 'Desenvolvido por Martseg para a Clarity Glass';

  var text = document.createElement('span');
  text.className = 'footer-brand-text';
  text.innerHTML = 'Desenvolvido pela <strong>Martseg</strong> para a <strong>Clarity Glass</strong>';

  brand.appendChild(img);
  brand.appendChild(text);
  footer.appendChild(brand);
});
